      "content": "{\n  \"name\": \"dsh-wechat\",\n  \"version\": \"0.16.1\",\n  \"description\": \"Bridge WeChat (iLink bot) to DeepSeek Harness (DSH)\",\n  \"type\": \"module\",\n  \"files\": [\n    \"dist/\",\n    \"resources/\",\n    \"docs/\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"LICENSE\",\n    \"package.json\"\n  ],\n  \"main\": \"./dist/index.js\",\n  \"types\": \"./dist/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"import\": \"./dist/index.js\"\n    },\n    \"./client\": \"./dist/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc && node scripts/copy-client.mjs\",\n    \"dev\": \"tsc --watch\",\n    \"test\": \"vitest run\",\n    \"test:watch\": \"vitest\",\n    \"release\": \"node scripts/release.mjs\",\n    \"prepublishOnly\": \"npm run build && npm test\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.0.0\",\n    \"@types/semver\": \"^7.8.0\",\n    \"qrcode-generator\": \"^2.0.4\",\n    \"semver\": \"^7.8.5\",\n    \"typescript\": \"^5.5.0\",\n    \"vitest\": \"^4.1.8\"\n  },\n  \"engines\": {\n    \"node\": \">=20.0.0\",\n    \"dsh\": \">=0.2.1-0 <0.3.0-0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \">=0.2.1-0 <0.3.0-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh\": {\n      \"optional\": true\n    }\n  },\n  \"dsh\": {\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-slots\"\n      ]\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/pan17/dsh-wechat.git\"\n  },\n  \"keywords\": [\n    \"wechat\",\n    \"dsh\",\n    \"deepseek-harness\",\n    \"cordis\",\n    \"bridge\",\n    \"agent\"\n  ]\n}\n"
