      "path": "src/dsh/sessions.ts",
      "content": "/**\n * DSH session mapper: binds a WeChat user to a live DSH agent.\n *\n * Creates fresh agents through `ctx.agents.create` (minting a durable\n * session id) or resumes persisted ones through `ctx.agents.resume` after\n * a DSH restart. All service access goes through `ctx.get(...)` with\n * undefined checks — this plugin has zero runtime coupling to\n * `@deepseek-ai/*` packages.\n */\n\nimport crypto from \"node:crypto\";\nimport { createUserMessage } from \"./messages.js\";\nimport type { BusyEnterBehavior } from \"./ops.js\";\nimport type {\n  Agent,\n  AgentHandle,\n  AgentSessionLike,\n  ContentBlock,\n  CreateAgentOptions,\n  ModelSelectionView,\n  ResumeAgentOptions,\n  SessionProjectionService,\n} from \"./types.js\";\nimport { modelSelectionFromProjection } from \"./types.js\";\nimport type { UserState } from \"../state.js\";\n\n/** Minimal structural surface of the `agents` registry service. */\nexport interface AgentsService {\n  create(options: CreateAgentOptions): Promise<AgentHandle>;\n  resume(options: ResumeAgentOptions): Promise<AgentHandle>;\n  get(id: string): Agent | undefined;\n  list(): Agent[];\n}\n\n/** Minimal structural surface of `ctx` (Cordis). */\nexport interface BridgeContext {\n  get<T = unknown>(name: string): T | undefined;\n  on(event: string, listener: (...args: unknown[]) => unknown): () => void;\n}\n\n/** Result of {@link AgentStore.ensure}. */\nexport interface EnsureAgentResult {\n  readonly agent: Agent | undefined;\n  /**\n   * Previous bound session id that failed to resume, when a replacement\n   * session was minted (`replaceOnResumeFailure: true`). Absent when the\n   * bound session loaded, or when replacement was not requested.\n   */\n  readonly replacedSessionId?: string;\n}\n\n/** Options for {@link AgentStore.ensure}. */\nexport interface EnsureAgentOptions {\n  /**\n   * When the bound session fails to resume (corrupt log, missing file,\n   * persistence validation), clear the binding and create a fresh session\n   * instead of leaving the user stuck. Used by the inbound message path.\n   * Management commands that name a specific session (`/s switch`) leave\n   * this off so a failed load does not silently mint a different id.\n   */\n  readonly replaceOnResumeFailure?: boolean;\n}\n\n/** Minimal workspace entity surface (dsh-workspace). */\ninterface WorkspaceEntity {\n  readonly path: string;\n  readonly title: string;\n  readonly sessionIds: readonly string[];\n  attachSession(sessionId: string): Promise<void>;\n}\n\n/**\n * Mint a durable session id for a WeChat-bound session — the SAME format the\n * GUI uses (`session-<uuid>`, the same mint the session controller uses). Uniform\n * ids keep WeChat-created sessions indistinguishable from GUI-created ones\n * everywhere (lists, workspace accounting, log exports).\n */\nexport function mintSessionId(): string {\n  return `session-${crypto.randomUUID()}`;\n}\n\nexport class AgentStore {\n  private readonly ensuring = new Map<string, Promise<EnsureAgentResult>>();\n\n  constructor(private readonly ctx: BridgeContext) {}\n\n  private agents(): AgentsService | undefined {\n    return this.ctx.get<AgentsService>(\"agents\");\n  }\n\n  /** The live agent for a bound user state, if any. */\n  get(user: UserState): Agent | undefined {\n    if (!user.sessionId) return undefined;\n    return this.agents()?.get(user.sessionId);\n  }\n\n  /**\n   * Ensure a live agent for the user state. Creates a fresh session when\n   * none is bound yet; resumes the persisted session otherwise.\n   * Returns `{ agent }` (agent undefined when the agents service is\n   * unavailable or create/resume failed). With `replaceOnResumeFailure`,\n   * a corrupt or unreadable bound session is unbound and replaced.\n   */\n  ensure(user: UserState, options?: EnsureAgentOptions): Promise<EnsureAgentResult> {\n    // Serialize check/create for this user. Re-read the mutable binding after\n    // the previous call finishes, including its resume-failure replacement.\n    const previous = this.ensuring.get(user.userId);\n    const run = (previous ?? Promise.resolve()).then(\n      () => this.ensureNow(user, options),\n      () => this.ensureNow(user, options),\n    );\n    this.ensuring.set(user.userId, run);\n    const clear = (): void => {\n      if (this.ensuring.get(user.userId) === run) this.ensuring.delete(user.userId);\n    };\n    void run.then(clear, clear);\n    return run;\n  }\n\n  private async ensureNow(user: UserState, options?: EnsureAgentOptions): Promise<EnsureAgentResult> {\n    const agents = this.agents();\n    if (!agents) return { agent: undefined };\n\n    let replacedSessionId: string | undefined;\n\n    if (user.sessionId) {\n      const live = agents.get(user.sessionId);\n      if (live) return { agent: live };\n      try {\n        const handle = await agents.resume({\n          resumeSessionId: user.sessionId,\n          setup: agentSetup,\n        });\n        await this.attachToWorkspace(user.cwd, user.sessionId);\n        return { agent: handle.agent };\n      } catch (err) {\n        console.error(`[dsh-wechat] resume session ${user.sessionId} failed: ${String(err)}`);\n        if (!options?.replaceOnResumeFailure) return { agent: undefined };\n        replacedSessionId = user.sessionId;\n        user.sessionId = \"\";\n      }\n    }\n\n    try {\n      // The preset this session will actually run: the deployment default\n      // (settings document first — the same one the GUI edits and /preset\n      // switch writes). Recording it in the header (like the GUI's\n      // composeAgent does) keeps /session list's Preset column populated and\n      // makes a later resume mount the same composition.\n      const rosterDefault = this.ctx.get<{ defaultId?: string }>(\"agentPresets\")?.defaultId;\n      const presetForSession = rosterDefault;\n      const sessionId = mintSessionId();\n      const handle = await agents.create({\n        sessionId,\n        meta: {\n          cwd: user.cwd,\n          ...(presetForSession ? { agentPreset: presetForSession } : {}),\n        },\n        setup: agentSetup,\n      });\n      // Persist the binding so a later restart resumes this session.\n      user.sessionId = sessionId;\n      await this.attachToWorkspace(user.cwd, sessionId);\n      return { agent: handle.agent, replacedSessionId };\n    } catch (err) {\n      console.error(`[dsh-wechat] create session failed: ${String(err)}`);\n      return { agent: undefined, replacedSessionId };\n    }\n  }\n\n  /**\n   * Account the session to the workspace owning `cwd` (create it on first\n   * use), exactly like the GUI's session.create remote does via\n   * `workspace.attachSession`. Without this, WeChat-created sessions fall\n   * into the sidebar's \"ungrouped\" bucket: the workspace registry derives\n   * membership from its durable `sessionIds` records, which only\n   * `attachSession` (or the startup bootstrap) populates.\n   */\n  private async attachToWorkspace(cwd: string, sessionId: string): Promise<void> {\n    const registry = this.ctx.get<{\n      create(path: string, title?: string): Promise<WorkspaceEntity>;\n      resolveByPath(path: string): Promise<WorkspaceEntity | undefined>;\n    }>(\"workspaceRegistry\");\n    if (!registry) return;\n    try {\n      let workspace = await registry.resolveByPath(cwd);\n      if (!workspace) workspace = await registry.create(cwd);\n      await workspace.attachSession(sessionId);\n    } catch (err) {\n      // Non-fatal: the session still works, it just shows ungrouped.\n      console.error(`[dsh-wechat] attach session ${sessionId} to workspace failed: ${String(err)}`);\n    }\n  }\n\n  /**\n   * Deliver a user-role message to the agent.\n   *\n   * `mode` mirrors the DSH `ui-conversation.busyEnter` preference (the GUI's\n   * 「繁忙时 Enter 键行为」): `\"queue\"` routes through `agent.followup` — an\n   * ordinary follow-up turn, the behavior while idle and the historical\n   * default; `\"steer\"` routes through `agent.steer` — an idle driver starts a\n   * turn, a running driver consumes the message at its nearest step boundary\n   * (a closed window degrades to the next waking queue turn, never lost).\n   * The caller resolves the mode from agent.status + the shared setting.\n   */\n  followup(\n    agent: Agent,\n    content: ContentBlock[],\n    mode: BusyEnterBehavior = \"queue\",\n    onCreated?: (messageId: string) => void,\n  ): string {\n    const message = createUserMessage({\n      content,\n      // kind 'user' — identical to messages sent from the GUI chat box, so\n      // the WeChat user's messages render as ordinary user messages (a\n      // 'plugin' source renders as \"context injection\" in the GUI).\n      source: { kind: \"user\" },\n    });\n    // Record the minted id BEFORE followup/steer. Those calls synchronously\n    // emit `agent/inbox/spliced`; the surface-prompt marker must already\n    // know this id or the splice handler treats the WeChat message as GUI.\n    onCreated?.(message.id);\n    if (mode === \"steer\") {\n      agent.steer(message);\n    } else {\n      agent.followup(message);\n    }\n    return message.id;\n  }\n}\n\n/**\n * Agent-scoped composition applied to every WeChat-bound session (fresh\n * create or resume): a preset mount joins the agent to its recorded (or\n * deployment-default) agent preset so the preset's tools and prompt sections\n * cover it — the same composition the GUI's `composeAgent` installs — and a\n * model-selection pair of waterfalls keeps the prompt variables and request\n * routing populated exactly like the GUI does. Registered on the agent's own\n * scoped context so it never leaks into other sessions.\n *\n * NOTE: the WeChat surface prompt (\"you are chatting through WeChat\") is NOT\n * registered here anymore — it lives in a global dynamic runtime context\n * registered by index.ts (`dsh-wechat-surface`), whose text is evaluated per assembly\n * from the bridge's per-session message-source map. That makes the prompt\n * follow the *message source* (WeChat vs GUI), so any session — old or new,\n * GUI- or WeChat-created — gets the WeChat prompt exactly while WeChat\n * messages drive it, and never while GUI messages drive it.\n */\n/**\n * DSH 0.1.5 removed `ctx.agent`; `setup` now receives `(agentCtx, agent)`.\n * Fall back to the legacy context property so a 0.1.2 host still works.\n */\nfunction setupAgent(agentCtx: unknown, agent?: Agent): Agent | undefined {\n  if (agent) return agent;\n  const legacy = (agentCtx as { agent?: Agent } | undefined)?.agent;\n  return legacy;\n}\n\n/**\n * Give a session that has no route at all a durable model selection.\n *\n * DSH 0.2.2 stops a step before any waterfall runs when the Agent has no\n * route: `preStep` reads `agent.model.current()` and throws \"has no\n * provider/model: set AgentOptions.provider and AgentOptions.model or record\n * a model selection\". `current()` only reads a recorded `model/selection` or\n * `AgentOptions` — never the log's request header. A WeChat-minted session is\n * created with neither (the bridge never knew the deployment route), and the\n * `agent/request` rewrite that used to fill it in at request time is gone, so\n * the first turn of every new session died.\n *\n * Record what the session would have run on anyway, in the same cascade the\n * bridge reports elsewhere: keep an existing route untouched, otherwise take\n * the resumed session's last request header (a legacy session keeps its\n * historical model), then the deployment default the GUI's new-session path\n * uses. Writing the selection is the GUI's own durable record, so the picker\n * shows it too.\n */\nfunction seedModelSelection(\n  ctx: { get?: <T = unknown>(name: string) => T | undefined },\n  agent: Agent | undefined,\n): void {\n  const model = (\n    agent as unknown as\n      | {\n          model?: {\n            current(): unknown;\n            select(selection: ModelSelectionView): void;\n          };\n        }\n      | undefined\n  )?.model;\n  if (!model || typeof model.current !== \"function\" || typeof model.select !== \"function\") {\n    return; // pre-0.2.2 host: the request waterfall owns the route instead.\n  }\n  try {\n    if (model.current() !== undefined) return;\n    const logged = (\n      agent as unknown as\n        | {\n            session?: {\n              requestHeader?():\n                | { config?: { provider?: string; model?: string; reasoningEffort?: string } }\n                | undefined;\n            };\n          }\n        | undefined\n    )?.session?.requestHeader?.()?.config;\n    const candidate: ModelSelectionView | undefined =\n      logged?.provider && logged.model\n        ? {\n            provider: logged.provider,\n            model: logged.model,\n            ...(logged.reasoningEffort ? { reasoningEffort: logged.reasoningEffort } : {}),\n          }\n        : ctx.get?.<{ currentSelection(): ModelSelectionView }>(\n            \"agentDefaultModel\",\n          )?.currentSelection();\n    if (!candidate?.provider || !candidate.model) return;\n    model.select(candidate);\n  } catch (err) {\n    // Non-fatal: the turn will surface the Host's own diagnostic if the\n    // deployment really has no default route to fall back to.\n    console.error(`[dsh-wechat] seed model selection failed: ${String(err)}`);\n  }\n}\n\nexport async function agentSetup(agentCtx: unknown, agent?: Agent): Promise<void> {\n  const ctx = agentCtx as {\n    get?: <T = unknown>(name: string) => T | undefined;\n    on?: (event: string, listener: (...args: unknown[]) => unknown) => void;\n  };\n  const live = setupAgent(agentCtx, agent);\n\n  // Preset mount — the GUI's composeAgent equivalent. The session's recorded\n  // preset (header.agentPreset, written at creation) decides its tools and\n  // prompt; an absent one falls back to the roster default (`mount` with no\n  // id). Without this, WeChat-created sessions lack the preset's tools\n  // (pwsh, fs, web, skill, …) and prompt sections entirely.\n  const presets = ctx.get?.<{\n    mount(agentCtx: unknown, id?: string): Promise<unknown>;\n  }>(\"agentPresets\");\n  if (presets) {\n    try {\n      await presets.mount(agentCtx, live?.session?.header?.agentPreset);\n    } catch (err) {\n      console.error(`[dsh-wechat] preset mount failed: ${String(err)}`);\n    }\n  }\n\n  // DSH 0.2.1 owns per-Session model selection in the Host (the GUI's\n  // `session.selectModel` appends `model/selection` and installs the\n  // selection). When that Remote is composed, the bridge must read the same\n  // durable `modelSelection` projection live: a snapshot captured here would\n  // keep forcing the model that happened to be current when the WeChat agent\n  // resumed — exactly the \"GUI switched but WeChat still uses the old model\"\n  // bug. On older hosts without the controller, the legacy frozen selection\n  // stays in place, and the bridge's global `agent/request` override (the\n  // `/model switch` fallback) still wins because it is registered earlier;\n  // on a host that owns the selection that override is a no-op instead (see\n  // `applyModelOverride`), so nothing can fight the step's fixed route.\n  const controller = ctx.get?.<{ selectModel?: unknown }>(\"sessionController\");\n  const hostOwnsSelection = typeof controller?.selectModel === \"function\";\n\n  // 0.2.2 refuses to start a step for a route-less Agent, before any\n  // waterfall runs; a WeChat-minted session has neither AgentOptions nor a\n  // recorded selection. Record one up front (no-op when the session already\n  // has a route). See `seedModelSelection`.\n  if (hostOwnsSelection) seedModelSelection(ctx, live);\n\n  if (!hostOwnsSelection) {\n    const logged = live?.session?.requestHeader?.()?.config;\n    const defaults = ctx.get?.<{ currentSelection(): ModelSelectionView }>(\n      \"agentDefaultModel\",\n    )?.currentSelection();\n    const selected: ModelSelectionView | undefined =\n      logged?.provider && logged.model\n        ? {\n            provider: logged.provider,\n            model: logged.model,\n            ...(logged.reasoningEffort ? { reasoningEffort: logged.reasoningEffort } : {}),\n          }\n        : defaults;\n    if (!selected?.provider || !selected.model) return;\n\n    ctx.on?.(\"system-prompt/assemble\", async (_assembly, _context, next) => {\n      const assembled = (await (next as () => Promise<{\n        variables?: Record<string, unknown>;\n      }>)()) as { variables?: Record<string, unknown> };\n      return {\n        ...assembled,\n        variables: {\n          ...assembled.variables,\n          provider: selected.provider,\n          model: selected.model,\n        },\n      };\n    });\n    ctx.on?.(\"agent/request\", async (_payload, next) => {\n      const resolved = (await (next as () => Promise<Record<string, unknown>>)()) as Record<string, unknown>;\n      return {\n        ...resolved,\n        provider: selected.provider,\n        model: selected.model,\n        ...(selected.reasoningEffort === undefined\n          ? {}\n          : { reasoningEffort: selected.reasoningEffort }),\n      };\n    });\n    return;\n  }\n\n  const defaultModel = ctx.get?.<{ currentSelection(): ModelSelectionView }>(\"agentDefaultModel\");\n  const projections = ctx.get?.<SessionProjectionService>(\"sessionProjections\");\n  const currentSelection = (): ModelSelectionView | undefined => {\n    const session = live?.session as unknown as AgentSessionLike | undefined;\n    if (session && projections) {\n      try {\n        const projected = modelSelectionFromProjection(\n          projections.snapshot(session)?.values?.[\"modelSelection\"],\n        );\n        if (projected?.provider && projected.model) return projected;\n      } catch {\n        // Projection unavailable for this session; fall through to the log.\n      }\n    }\n    const logged = live?.session?.requestHeader?.()?.config;\n    if (logged?.provider && logged.model) {\n      return {\n        provider: logged.provider,\n        model: logged.model,\n        ...(logged.reasoningEffort ? { reasoningEffort: logged.reasoningEffort } : {}),\n      };\n    }\n    return defaultModel?.currentSelection();\n  };\n\n  // Publish the Host's selection as prompt variables ONLY. On this branch the\n  // Host is the single owner of the route, so the bridge must never rewrite\n  // `agent/request`: DSH 0.2.2 captures the step's provider/model/reasoning\n  // effort BEFORE that waterfall runs and throws when a listener returns a\n  // different one (\"use agent.model.select() before step preparation\"), which\n  // failed the whole turn. The switch path is `sessionController.selectModel`\n  // and both the route and these variables read the same durable\n  // `modelSelection` projection the GUI shows, so they cannot disagree.\n  ctx.on?.(\"system-prompt/assemble\", async (_assembly, _context, next) => {\n    const selected = currentSelection();\n    const assembled = (await (next as () => Promise<{\n      variables?: Record<string, unknown>;\n    }>)()) as { variables?: Record<string, unknown> };\n    if (!selected?.provider || !selected.model) return assembled;\n    return {\n      ...assembled,\n      variables: {\n        ...assembled.variables,\n        provider: selected.provider,\n        model: selected.model,\n      },\n    };\n  });\n}\n"
    },
    {
      "path": "src/index.ts",
      "content": "/**\n * dsh-wechat — Bridge WeChat (iLink bot) to DeepSeek Harness (DSH).\n *\n * Cordis host plugin entry. Loaded through the package's cordis.patch.yml\n * bundle layer (`- insert: - id: dsh-wechat name: 'dsh-wechat'`).\n *\n * Zero runtime dependencies on `@deepseek-ai/*` packages: every DSH\n * service is read through `ctx.get(...)` and all message/value types are\n * constructed by local vendors or structural shapes.\n */\n\nimport { WeChatDSHBridge } from \"./bridge/bridge.js\";\nimport { formatHelp } from \"./bridge/slash.js\";\nimport { helpCatalog } from \"./help-catalog.js\";\nimport { ConfigStore, type EditableConfig } from \"./config-store.js\";\nimport { defaultConfig, normalizeWorkStepsConfig, type WeChatDSHConfig, type WorkStepsMode } from \"./config.js\";\nimport { qrSvgFor } from \"./qr.js\";\nimport { sessionIdFrom, sessionIdFromAssembleContext, weChatSurfaceText } from \"./surface-prompt.js\";\nexport { sessionIdFrom };\n\nexport const name = \"dsh-wechat\";\nexport const inject: string[] = [];\n\n/** Plugin config accepted from the composition row's `config:` block. */\nexport interface PluginConfig {\n  baseUrl?: string;\n  cdnBaseUrl?: string;\n  botType?: string;\n  storageDir?: string;\n  cwd?: string;\n  textChunkLimit?: number;\n  cardTimeoutMs?: number;\n  /** @deprecated Folded into `workSteps`; kept for composition-config migration. */\n  silent?: boolean;\n  /** @deprecated Folded into `workSteps`; kept for composition-config migration. */\n  finalOnly?: boolean;\n  /** 工作步骤展示: minimal / concise / standard. */\n  workSteps?: WorkStepsMode;\n  /** Whole-answer completion notices (`notifyTaskEvents` must also be on). */\n  notifyTaskFullReply?: boolean;\n  finalOnlyIdleMs?: number;\n  finalOnlyCeilingMs?: number;\n  surfacePromptEnabled?: boolean;\n  surfacePrompt?: string;\n  allowRemotePermissionEscalation?: boolean;\n  allowAnyFilePath?: boolean;\n  maxOutgoingFileBytes?: number;\n  mergeEnabled?: boolean;\n  mergeSilenceMs?: number;\n  mergeMaxMsgs?: number;\n  mergeSuffixTokens?: boolean;\n  mergeForcedReleaseMs?: number;\n  mediaMergeEnabled?: boolean;\n  mediaHoldMs?: number;\n  mediaAtRefEnabled?: boolean;\n  statusMode?: \"brief\" | \"full\";\n}\n\nexport function apply(ctx: unknown, rawConfig: PluginConfig = {}): () => Promise<void> {\n  // Migrate the removed silent/finalOnly keys on a copy so the caller's\n  // composition object is never mutated. A valid workSteps wins.\n  const raw = { ...rawConfig } as Record<string, unknown>;\n  normalizeWorkStepsConfig(raw);\n  const baseConfig: WeChatDSHConfig = {\n    ...defaultConfig(),\n    ...pickDefined(raw as PluginConfig),\n  };\n  const configStore = new ConfigStore(baseConfig.storageDir);\n  const config = configStore.resolve(baseConfig);\n  const context = ctx as {\n    get<T = unknown>(name: string): T | undefined;\n    on(\n      event: string,\n      listener: (...args: unknown[]) => unknown,\n      options?: boolean | { prepend?: boolean; global?: boolean },\n    ): () => void;\n    inject?: (deps: string[], callback: (ctx: unknown) => unknown) => unknown;\n    /**\n     * Cordis lifecycle effect. A disposer returned from the body is run in\n     * reverse order when the owning fiber unloads. Optional in the declared\n     * shape so a host that predates it degrades to the `ctx.inject` fiber\n     * disposer instead of failing to apply.\n     */\n    effect?: (body: () => unknown) => unknown;\n  };\n\n  const bridge = new WeChatDSHBridge(context, config, undefined, configStore);\n\n  // ─── Session event feed: assistant output → WeChat ───\n  context.on(\"session/event\", (session, event) => {\n    const sessionId = sessionIdFrom(session);\n    if (!sessionId) {\n      console.warn(\"[dsh-wechat] session/event dropped: no session id on payload\");\n      return;\n    }\n    bridge.handleSessionEvent(sessionId, event as { type: string; [k: string]: unknown });\n  });\n  console.log(\"[dsh-wechat] session/event listener attached\");\n  context.on(\"agent/assistant-stream\", (payload) => {\n    const { agent, frame } = payload as { agent?: { id?: string }; frame?: import(\"./dsh/types.js\").AssistantStreamFrame };\n    if (agent?.id && frame) bridge.handleAssistantStream(agent.id, frame);\n  });\n  context.on(\"session/disposed\", (session) => {\n    const sessionId = sessionIdFrom(session);\n    if (sessionId) bridge.clearSessionOutput(sessionId);\n  });\n\n  // ─── Agent idleness → 极简模式 (per-task hold) quiescence ───\n  // The goal round-driver wakes the NEXT round exactly when `agent.status`\n  // flips to `idle`, so this is also the signal that tells the hold \"more\n  // rounds are coming\" (running cancels the countdown) versus \"the task is\n  // genuinely finished\" (idle arms it). `agent.id` IS the session id in DSH\n  // (`Agent.id: SessionId`), so no session lookup is needed.\n  context.on(\"agent/status\", (payload) => {\n    const data = payload as { agent?: { id?: string }; status?: string };\n    const sessionId = data?.agent?.id;\n    const status = data?.status;\n    if (!sessionId || !status) return;\n    bridge.handleAgentStatus(sessionId, status);\n  });\n\n  // ─── Agent errors → WeChat notification ───\n  context.on(\"agent/error\", (payload) => {\n    const agentId = (payload as { agent?: { id?: string } })?.agent?.id;\n    if (!agentId) return;\n    bridge.handleAgentError(agentId, (payload as { error?: unknown })?.error);\n  });\n\n  // ─── Model overrides: /model switch applies to the live agent's next\n  // request by rewriting the frozen call config (same cooperative pattern\n  // as dsh-agent's installModelSelection: await next(), then replace). ───\n  context.on(\"agent/request\", async (payload, next) => {\n    const agentId = (payload as { agent?: { id?: string } })?.agent?.id;\n    const nextFn = next as () => Promise<unknown>;\n    const config = await nextFn();\n    if (!agentId || !bridge.userForAgent(agentId)) return config;\n    return bridge.applyModelOverride(config as { provider: string; model: string }, agentId);\n  });\n\n  // ─── send_wechat tool: agent-initiated push to the bound user ───\n  // (Approval/question cards are fully native — the Host waterfalls below\n  // race WeChat against the GUI so whoever answers first wins.)\n  //\n  // The registration ALWAYS goes through `ctx.effect` / the `ctx.inject`\n  // fiber so its disposer is parked on the plugin's fiber: `register()`\n  // returns the exact disposer that unregisters the tool, and discarding\n  // it leaves `send_wechat` bound to a stale bridge after the plugin is\n  // reloaded or removed. Both paths dispose identically — `effect` gives\n  // the disposer an explicit, labelled owner and is the host's own idiom\n  // (see `packages/host/open-in-app`).\n  if (typeof context.inject === \"function\") {\n    context.inject([\"tools\"], (toolsCtx) => {\n      const toolsService = (toolsCtx as {\n        get<T = unknown>(name: string): T | undefined;\n      }).get<{\n        register(definition: unknown): (() => void) | undefined;\n      }>(\"tools\");\n      if (!toolsService) return;\n\n      const registerSendWechatTool = () => {\n        const dispose = toolsService.register({\n          name: \"send_wechat\",\n          description:\n            \"Send a text message or a local file to a WeChat user. \" +\n            \"If the calling session is bound to a WeChat user, the message goes to that user; \" +\n            \"otherwise it goes to the first known WeChat user (single-user deployments are the norm). \" +\n            \"Use this to proactively push results, confirmations, or files to WeChat. \" +\n            \"A file must live inside the calling session's working directory or a registered \" +\n            \"workspace, and must be under the configured size limit; anything else is refused.\",\n          parameters: {\n            type: \"object\",\n            properties: {\n              text: {\n                type: \"string\",\n                description: \"The text message to send to WeChat.\",\n              },\n              file_path: {\n                type: \"string\",\n                description:\n                  \"Path of a local file to send to WeChat. Must resolve inside the calling \"\n                  + \"session's working directory or a registered workspace (unless the operator \"\n                  + \"enabled allowAnyFilePath), and must fit maxOutgoingFileBytes.\",\n              },\n            },\n          },\n          output: {\n            schema: {\n              type: \"object\",\n              additionalProperties: false,\n              properties: {\n                ok: { type: \"boolean\" },\n                message: { type: \"string\" },\n              },\n            },\n            render: (_args: unknown, value: unknown) => [{ type: \"text\", text: JSON.stringify(value) }],\n          },\n          async execute(args: { text?: string; file_path?: string }, exec: { agent?: { id?: string } }) {\n            return bridge.handleSendWeChat(exec.agent?.id ?? \"\", args);\n          },\n        });\n        return () => {\n          if (typeof dispose === \"function\") dispose();\n        };\n      };\n\n      if (typeof context.effect === \"function\") {\n        context.effect(registerSendWechatTool);\n      } else {\n        // Legacy host without `ctx.effect`: `register()` still binds the\n        // tool to the calling (injected) scope, and `ctx.inject` returns\n        // the child fiber that owns it, so unload already unregisters it.\n        registerSendWechatTool();\n      }\n    });\n  } else {\n    console.warn(\"[dsh-wechat] ctx.inject unavailable; send_wechat tool disabled\");\n  }\n\n  // ─── Approval / question cards: Host waterfalls (GUI-equivalent mirror) ───\n  // Untagged listeners are admitted globally by scopeTarget, so a host-level\n  // answerer sees every session. prepend:true so we wrap next() (the GUI\n  // terminal answerer) instead of running after it. No WeChat peer →\n  // immediately next() so the GUI remains the sole answerer. Errors fall\n  // through to next() rather than collapsing the GUI card.\n  context.on(\"approval/request\", async (req, next) => {\n    const nextFn = next as () => Promise<\"allowed-once\" | \"rejected\" | \"cancelled\" | \"unavailable\">;\n    try {\n      return await bridge.answerApprovalRequest(req as never, nextFn);\n    } catch (err) {\n      console.error(`[dsh-wechat] approval/request answerer failed: ${String(err)}`);\n      return nextFn();\n    }\n  }, { prepend: true });\n  context.on(\"user-questions/request\", async (req, next) => {\n    const nextFn = next as () => Promise<unknown>;\n    try {\n      return await bridge.answerQuestionRequest(req as never, nextFn as never);\n    } catch (err) {\n      // WeChat /rq cancels by rejecting the waiter; rethrow so the Host\n      // settles the ask. ASK_CANCELLED = user closed the card (Web X);\n      // ASK_ABORTED = turn/signal abort. Other failures fall through to GUI.\n      const code = err && typeof err === \"object\" ? (err as { code?: string }).code : undefined;\n      if (code === \"ASK_CANCELLED\" || code === \"ASK_ABORTED\") {\n        throw err;\n      }\n      console.error(`[dsh-wechat] user-questions/request answerer failed: ${String(err)}`);\n      return nextFn();\n    }\n  }, { prepend: true });\n  console.log(\"[dsh-wechat] approval/question waterfall answerers attached\");\n\n  // ─── DSH native command registry (ctx.commands) ───\n// When the host composes `@deepseek-ai/dsh-commands`, late-bind the\n// command surface so WeChat can dispatch `/plan`, `/goal`, `/compact`\n// and any other plugin-registered slash command through the same\n// native handler the GUI uses. If the registry is not composed\n// (minimal headless profiles, host version drift, etc.) we fall through\n// to the local whitelist exactly like before — no behavioral change.\nif (typeof context.inject === \"function\") {\n  context.inject([\"commands\"], (cmdCtx) => {\n    const commands = (cmdCtx as {\n      get<T = unknown>(name: string): T | undefined;\n    }).get<{\n      find: unknown;\n      execute: unknown;\n    }>(\"commands\");\n    if (!commands) {\n      console.warn(\"[dsh-wechat] ctx.commands unavailable; 原生命令层禁用，回落到本地白名单\");\n      return;\n    }\n    // Cast through the bridge's structural surface — we never reference\n    // the actual `@deepseek-ai/dsh-commands` types here, so zero runtime\n    // dep is added.\n    bridge.attachCommands(commands as never);\n    console.log(\"[dsh-wechat] 原生命令层已挂载 (/plan、/goal 等通过 ctx.commands 分发)\");\n  });\n} else {\n  console.warn(\"[dsh-wechat] ctx.inject unavailable; 原生命令层禁用，回落到本地白名单\");\n}\n\n// ─── Dynamic WeChat surface prompt (per-message-source) ───\n  // Registered as a GLOBAL RUNTIME CONTEXT (not a prompt section): DSH's\n  // system-prompt assembly applies a \"complete-section replacement\" pass to\n  // sections (a preset's complete section replaces ALL ordinary sections,\n  // which would drop a section-registered surface prompt — exactly the\n  // failure observed), while CONTEXTS are assembled on an independent path\n  // (\"Current runtime context\" snapshot) that complete replacement never\n  // touches. The context text is evaluated per assembly: the bridge tracks\n  // the most recent user-message source per session, and the context returns\n  // the WeChat prompt ONLY while the session's last user message came from\n  // WeChat; otherwise it returns \"\" (empty contexts are filtered out, so\n  // GUI-driven assemblies are untouched). Global registration means EVERY\n  // agent — old or new, GUI- or WeChat-created, live or resumed — gets the\n  // same dynamic context, so the WeChat prompt follows the message source\n  // rather than the session's setup path.\n  if (typeof context.inject === \"function\") {\n    context.inject([\"systemPrompt\"], (promptCtx) => {\n      const systemPrompt = (promptCtx as {\n        get<T = unknown>(name: string): T | undefined;\n      }).get<{\n        context(entry: {\n          name: string;\n          order: number;\n          text: string | ((context: unknown) => string);\n        }): unknown;\n      }>(\"systemPrompt\");\n      if (!systemPrompt) {\n        console.warn(\"[dsh-wechat] systemPrompt unavailable; WeChat surface prompt disabled\");\n        return;\n      }\n      systemPrompt.context({\n        name: \"dsh-wechat-surface\",\n        order: 50,\n        text: (context) => {\n          const sessionId = sessionIdFromAssembleContext(context);\n          const source = sessionId ? bridge.surfaceSourceFor(sessionId) : undefined;\n          const cfg = bridge.getConfig();\n          return weChatSurfaceText({\n            enabled: cfg.surfacePromptEnabled,\n            prompt: cfg.surfacePrompt,\n            source,\n          });\n        },\n      });\n    });\n  }\n\n  // ─── QR page + settings-page API ───\n  // The webserver row activates only after `webStartup` resolves (it waits on\n  // inject), so `ctx.get('webServer')` at apply time is undefined. Use the\n  // conditional-inject pattern to register the routes once the service is\n  // available; the bridge itself works without them (QR URL is logged).\n  if (typeof context.inject === \"function\") {\n    context.inject([\"webServer\"], (httpCtx) => {\n      const webServer = (httpCtx as {\n        get<T = unknown>(name: string): T | undefined;\n      }).get<{\n        register(route: {\n          kind: \"exact\" | \"prefix\";\n          path: string;\n          handler: (req: unknown, res: unknown) => void;\n        }): unknown;\n        /** Real bound origin (protocol + host + port). Declared optional so an\n         *  older host that lacks it still gets the routes. */\n        getOrigin?(): string;\n      }>(\"webServer\");\n      if (!webServer) return;\n\n      // QR login page (standalone viewer; the settings page is the primary UI).\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/qr\",\n        handler: (_req, res) => {\n          const response = res as HttpResponse;\n          response.setHeader(\"Content-Type\", \"text/html; charset=utf-8\");\n          response.setHeader(\"Cache-Control\", \"no-store\");\n          response.end(QR_PAGE);\n        },\n      });\n      // QR image: the iLink qrcode_img_content URL is an HTML page, not an\n      // image — the URL string is encoded into a QR server-side instead.\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/api/qr-image\",\n        handler: (_req, res) => {\n          const status = bridge.getStatus() as { qrUrl?: string };\n          const response = res as HttpResponse;\n          if (!status.qrUrl) {\n            response.statusCode = 404;\n            response.setHeader(\"Content-Type\", \"text/plain; charset=utf-8\");\n            response.setHeader(\"Cache-Control\", \"no-store\");\n            response.end(\"no QR available\");\n            return;\n          }\n          response.statusCode = 200;\n          response.setHeader(\"Content-Type\", \"image/svg+xml; charset=utf-8\");\n          response.setHeader(\"Cache-Control\", \"no-store\");\n          response.end(qrSvgFor(status.qrUrl));\n        },\n      });\n      // QR page poll endpoint (phase/qrUrl/botId/error).\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/status\",\n        handler: (_req, res) => {\n          sendJson(res, 200, bridge.getStatus());\n        },\n      });\n\n      // Settings-page API.\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/api/status\",\n        handler: (_req, res) => {\n          sendJson(res, 200, bridge.getStatus());\n        },\n      });\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/api/help\",\n        handler: (_req, res) => {\n          // `text` stays the verbatim `/help` reply (the WeChat side and any\n          // older client keep working); `catalog` is the settings page's\n          // plain-language view of the same command set. Both come from this\n          // install, so they cannot disagree about which commands exist —\n          // `tests/help-catalog.test.ts` pins the two sets together.\n          sendJson(res, 200, { ok: true, text: formatHelp(), catalog: helpCatalog() });\n        },\n      });\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/api/config\",\n        handler: async (req, res) => {\n          try {\n            const patch = (await readJsonBody(req)) as Partial<EditableConfig>;\n            const stored = configStore.update(patch);\n            const result = await bridge.updateConfig(stored);\n            sendJson(res, 200, { ok: true, ...result });\n          } catch (err) {\n            sendJson(res, 400, { ok: false, message: String(err) });\n          }\n        },\n      });\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/api/relogin\",\n        handler: async (_req, res) => {\n          const result = await bridge.relogin();\n          sendJson(res, 200, { ok: result.ok, message: result.message });\n        },\n      });\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/api/logout\",\n        handler: async (_req, res) => {\n          const result = await bridge.logout();\n          sendJson(res, 200, { ok: result.ok, message: result.message });\n        },\n      });\n      // Per-user toggles (silent / crossSessionNotify) for the WebUI\n      webServer.register({\n        kind: \"prefix\",\n        path: \"/wechat/api/user/\",\n        handler: async (req, res) => {\n          try {\n            const httpReq = req as { url?: string; method?: string; path?: string };\n            const rawUrl = (httpReq.url ?? httpReq.path ?? \"\") as string;\n            const prefix = \"/wechat/api/user/\";\n            const after = rawUrl.startsWith(prefix) ? rawUrl.slice(prefix.length) : rawUrl.split(\"/\").pop() ?? \"\";\n            const userId = decodeURIComponent(after.split(\"?\")[0]!.split(\"#\")[0]!.trim());\n            if (!userId) {\n              sendJson(res, 400, { ok: false, message: \"缺少 userId\" });\n              return;\n            }\n            const patch = (await readJsonBody(req)) as { silent?: boolean; crossSessionNotify?: string };\n            const normalized: { silent?: boolean; crossSessionNotify?: \"inherit\" | \"on\" | \"off\" } = {};\n            if (typeof patch.silent === \"boolean\") normalized.silent = patch.silent;\n            if (patch.crossSessionNotify === \"on\" || patch.crossSessionNotify === \"off\" || patch.crossSessionNotify === \"inherit\") {\n              normalized.crossSessionNotify = patch.crossSessionNotify;\n            }\n            const result = bridge.updateUserConfig(userId, normalized);\n            sendJson(res, result.ok ? 200 : 400, result);\n          } catch (err) {\n            sendJson(res, 400, { ok: false, message: String(err) });\n          }\n        },\n      });\n      webServer.register({\n        kind: \"exact\",\n        path: \"/wechat/api/user\",\n        handler: async (req, res) => {\n          try {\n            const patch = (await readJsonBody(req)) as { userId?: string; silent?: boolean; crossSessionNotify?: string };\n            const userId = typeof patch.userId === \"string\" ? patch.userId.trim() : \"\";\n            if (!userId) {\n              sendJson(res, 400, { ok: false, message: \"缺少 userId\" });\n              return;\n            }\n            const normalized: { silent?: boolean; crossSessionNotify?: \"inherit\" | \"on\" | \"off\" } = {};\n            if (typeof patch.silent === \"boolean\") normalized.silent = patch.silent;\n            if (patch.crossSessionNotify === \"on\" || patch.crossSessionNotify === \"off\" || patch.crossSessionNotify === \"inherit\") {\n              normalized.crossSessionNotify = patch.crossSessionNotify;\n            }\n            const result = bridge.updateUserConfig(userId, normalized);\n            sendJson(res, result.ok ? 200 : 400, result);\n          } catch (err) {\n            sendJson(res, 400, { ok: false, message: String(err) });\n          }\n        },\n      });\n      // The port is chosen at listen time (3080 only when free), so print the\n      // origin the server actually bound instead of a hardcoded guess. The\n      // same address serves the GUI, so this is the URL the user already has.\n      let origin = \"\";\n      try {\n        origin = webServer.getOrigin?.() ?? \"\";\n      } catch {\n        origin = \"\"; // not listening yet — the path alone is still actionable\n      }\n      console.log(\n        origin\n          ? `[dsh-wechat] Settings UI available: 设置 → WeChat；扫码页 ${origin}/wechat/qr`\n          : \"[dsh-wechat] Settings UI available: 设置 → WeChat；扫码页 <DSH 地址>/wechat/qr\",\n      );\n    });\n  } else {\n    console.log(\"[dsh-wechat] ctx.inject unavailable; QR page disabled (login QR is logged)\");\n  }\n\n  // Start the bridge (token resume or QR login), stop on dispose.\n  void bridge.start().catch((err) => {\n    console.error(`[dsh-wechat] bridge start failed: ${String(err)}`);\n  });\n\n  const stopBridge = (): Promise<void> => bridge.stop();\n  // Park the teardown on the plugin's OWN fiber (`ctx.effect`) and only fall\n  // back to the returned function. This host's cordis does not turn a\n  // functional plugin's return value into a disposer, so returning it alone\n  // left `bridge.stop()` uncalled: the iLink long poll, its timers and its\n  // socket survived dispose, the host process could never drain its event\n  // loop, and the desktop shell killed it after the 10 s graceful deadline\n  // (which is what refused every in-app update).\n  //\n  // Both paths are registered on purpose: `stop()` is idempotent, so a host\n  // that honours the return value as well cannot tear down twice.\n  if (typeof context.effect === \"function\") {\n    context.effect(() => stopBridge);\n  }\n  return stopBridge;\n}\n\nfunction pickDefined(raw: PluginConfig): Partial<WeChatDSHConfig> {\n  const out: Partial<WeChatDSHConfig> = {};\n  for (const [key, value] of Object.entries(raw)) {\n    if (value !== undefined) {\n      (out as Record<string, unknown>)[key] = value;\n    }\n  }\n  return out;\n}\n\n// ─── HTTP helpers for the webServer routes ───\n\ninterface HttpResponse {\n  statusCode?: number;\n  setHeader(name: string, value: string): void;\n  end(chunk: string): void;\n}\n\nfunction sendJson(res: unknown, status: number, body: unknown): void {\n  const response = res as HttpResponse;\n  response.statusCode = status;\n  response.setHeader(\"Content-Type\", \"application/json; charset=utf-8\");\n  response.setHeader(\"Cache-Control\", \"no-store\");\n  response.end(JSON.stringify(body));\n}\n\nfunction readJsonBody(req: unknown): Promise<unknown> {\n  return new Promise((resolve, reject) => {\n    const chunks: Buffer[] = [];\n    const stream = req as NodeJS.ReadableStream & {\n      on(event: string, listener: (...args: unknown[]) => void): unknown;\n    };\n    stream.on(\"data\", (chunk: unknown) => {\n      if (typeof chunk === \"string\") chunks.push(Buffer.from(chunk));\n      else if (chunk instanceof Uint8Array) chunks.push(Buffer.from(chunk));\n    });\n    stream.on(\"end\", () => {\n      const raw = Buffer.concat(chunks).toString(\"utf-8\");\n      if (!raw.trim()) {\n        resolve({});\n        return;\n      }\n      try {\n        resolve(JSON.parse(raw));\n      } catch (err) {\n        reject(new Error(`invalid JSON body: ${String(err)}`));\n      }\n    });\n    stream.on(\"error\", reject);\n  });\n}\n\n/** Standalone QR login page (no client build needed). */\nconst QR_PAGE = `<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>DSH 微信登录</title>\n<style>\n  body { font-family: system-ui, sans-serif; background: #f5f5f5; display: flex; justify-content: center; padding: 2rem; }\n  .card { background: #fff; border-radius: 12px; padding: 2rem; max-width: 420px; width: 100%; box-shadow: 0 2px 12px rgba(0,0,0,.08); text-align: center; }\n  h1 { font-size: 1.2rem; margin: 0 0 .5rem; }\n  .state { color: #666; margin: 1rem 0; min-height: 1.5em; }\n  img.qr { width: 260px; height: 260px; border: 1px solid #eee; border-radius: 8px; }\n  .error { color: #c0392b; white-space: pre-wrap; }\n  .ok { color: #27ae60; font-weight: 600; }\n</style>\n</head>\n<body>\n<div class=\"card\">\n  <h1>📱 DSH 微信助手 — 扫码登录</h1>\n  <div id=\"state\" class=\"state\">正在获取二维码…</div>\n  <img id=\"qr\" class=\"qr\" alt=\"QR\" style=\"display:none\" />\n  <div id=\"err\" class=\"error\"></div>\n  <p style=\"color:#999;font-size:.8rem\">用微信扫描二维码，确认登录后本页自动刷新。二维码 5 分钟有效，过期自动刷新。</p>\n</div>\n<script>\n  async function poll() {\n    try {\n      const res = await fetch('/wechat/status');\n      const data = await res.json();\n      const state = document.getElementById('state');\n      const qr = document.getElementById('qr');\n      const err = document.getElementById('err');\n      err.textContent = '';\n      if (data.phase === 'logged-in') {\n        state.className = 'state ok';\n        state.textContent = '✅ 已登录 (Bot: ' + (data.botId || '') + ')';\n        qr.style.display = 'none';\n        return;\n      }\n      if (data.phase === 'failed') {\n        state.textContent = '❌ 登录失败';\n        err.textContent = data.error || '';\n        return;\n      }\n      if (data.phase === 'scaned') {\n        state.textContent = '已扫码，请在微信中确认…';\n      } else {\n        state.textContent = data.qrUrl ? '请用微信扫描下方二维码' : '正在获取二维码…';\n      }\n      if (data.qrUrl) {\n        qr.src = '/wechat/api/qr-image?v=' + encodeURIComponent(data.qrUrl);\n        qr.style.display = 'block';\n      }\n    } catch (e) {\n      document.getElementById('state').textContent = '无法连接 DSH（' + e + '）';\n    }\n    setTimeout(poll, 2000);\n  }\n  poll();\n</script>\n</body>\n</html>`;\n"
    },
    {
      "path": "src/state.ts",
      "content": "/**\n * Durable per-user bridge state: session mapping, the legacy silent mirror,\n * and workspace choices. Presets deliberately live elsewhere: the bound session's preset is\n * recorded in its own session log (`agent-preset/selected`), and the\n * new-session default lives in the DSH settings document\n * (`agent-preset-registry.selectedDefault`) — the same one the GUI settings\n * page edits and `/preset default` writes. Nothing about a preset is a\n * per-WeChat-user preference, so nothing about it belongs in this file.\n *\n * Mirrors the reference project's UserState (wechat-opencode) but keeps\n * ONLY what the DSH bridge needs. Persisted to `~/.dsh-wechat/state.json`\n * so restarts restore the WeChat user → DSH session mapping.\n */\n\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { ensurePrivateDir, writePrivateFile } from \"./utils/secure-fs.js\";\n\nexport interface UserState {\n  /** The WeChat user id this state belongs to. */\n  userId: string;\n  /** Bound DSH session id. */\n  sessionId: string;\n  /** Working directory the bound session was created with. */\n  cwd: string;\n  /**\n    * Whether the user explicitly switched workspaces (/workspace, /session\n    * switch). Explicit choices are NOT overwritten by the settings-page cwd\n    * default; users without this flag follow the settings default.\n    */\n  cwdExplicit?: boolean;\n  /**\n   * Legacy per-user silent mirror. Delivery reads `config.workSteps`; this\n   * field only feeds the one-time migration from old `state.json` files and\n   * the legacy `/wechat/api/user` endpoint.\n   */\n  silent: boolean;\n  /** Cross-session notification preference (default inherit -> follows global config). */\n  crossSessionNotify?: \"inherit\" | \"on\" | \"off\";\n  /** Sessions this user has ever been bound to — used for cross-session recipient resolution. */\n  watchedSessions?: string[];\n}\n\n/** One globally ordered outbound queue for the bridge's single WeChat peer. */\nexport type OutboundMessage =\n  | { kind: \"text\"; text: string }\n  | { kind: \"file\"; filePath: string; fileName: string };\n\n/**\n * Soft cap for the outbound FIFO. Reaching it makes `parkOutbound` try to\n * force-send the oldest item instead of dropping it, so a full queue means\n * \"try harder\", not \"discard\".\n */\nexport const MAX_OUTBOUND_QUEUE = 100;\n\n/**\n * Hard ceiling for the outbound FIFO — the actual memory bound.\n *\n * The soft cap alone cannot bound memory: when the force-send fails (invalid\n * token, gateway rejection, closed message window) nothing leaves the queue,\n * yet the caller still appends. Without a ceiling the queue — and the\n * `state.json` snapshot written from it — grows without limit for as long as\n * the outage lasts. This ceiling is the point where the oldest item is\n * dropped *with a loud log* instead, trading the least-recent message for a\n * bounded process. It sits well above the soft cap so the force-send path has\n * room to work before any loss is contemplated.\n */\nexport const MAX_OUTBOUND_QUEUE_HARD = MAX_OUTBOUND_QUEUE * 4;\n\nexport interface OutboundState {\n  version: 1;\n  peerUserId: string;\n  messageCount: number;\n  queue: OutboundMessage[];\n}\n\nexport interface BridgeStateFile {\n  users: Record<string, UserState>;\n  /** Single-peer send-window state; absent in legacy files and when empty. */\n  outbound?: OutboundState;\n}\n\nfunction normalizeOutbound(value: unknown): OutboundState | undefined {\n  if (!value || typeof value !== \"object\") return undefined;\n  const raw = value as { version?: unknown; peerUserId?: unknown; messageCount?: unknown; queue?: unknown };\n  if (raw.version !== 1 || typeof raw.peerUserId !== \"string\" || !raw.peerUserId) return undefined;\n\n  const count = typeof raw.messageCount === \"number\" && Number.isFinite(raw.messageCount)\n    ? Math.max(0, Math.min(10, Math.floor(raw.messageCount)))\n    : 0;\n  const queue: OutboundMessage[] = [];\n  if (Array.isArray(raw.queue)) {\n    for (const item of raw.queue) {\n      if (!item || typeof item !== \"object\") continue;\n      const candidate = item as Record<string, unknown>;\n      if (candidate.kind === \"text\" && typeof candidate.text === \"string\") {\n        queue.push({ kind: \"text\", text: candidate.text });\n      } else if (\n        candidate.kind === \"file\" &&\n        typeof candidate.filePath === \"string\" && candidate.filePath &&\n        typeof candidate.fileName === \"string\" && candidate.fileName\n      ) {\n        queue.push({ kind: \"file\", filePath: candidate.filePath, fileName: candidate.fileName });\n      }\n    }\n  }\n\n  return {\n    version: 1,\n    peerUserId: raw.peerUserId,\n    messageCount: count,\n    // The reload cap MUST match the runtime hard ceiling, not the soft cap:\n    // the runtime queue legally holds up to `MAX_OUTBOUND_QUEUE_HARD` (400)\n    // entries, so keeping only the last 100 here silently discarded items\n    // 101–400 of a full queue on every restart. `persistOutboundState` writes\n    // the whole bounded set, so a reload restores exactly what was saved.\n    queue: queue.slice(-MAX_OUTBOUND_QUEUE_HARD),\n  };\n}\n\nexport class StateStore {\n  private readonly filePath: string;\n  private state: BridgeStateFile;\n\n  constructor(storageDir: string) {\n    this.filePath = path.join(storageDir, \"state.json\");\n    this.state = this.load();\n  }\n\n  private load(): BridgeStateFile {\n    try {\n      if (fs.existsSync(this.filePath)) {\n        const parsed = JSON.parse(fs.readFileSync(this.filePath, \"utf-8\")) as BridgeStateFile;\n        if (parsed && typeof parsed === \"object\" && parsed.users) {\n          // Normalize legacy files: ensure optional fields have safe defaults\n          for (const user of Object.values(parsed.users)) {\n            if (!Array.isArray(user.watchedSessions)) {\n              // Seed history with current binding so old users get at least their present session\n              user.watchedSessions = user.sessionId ? [user.sessionId] : [];\n            }\n            if (user.crossSessionNotify !== \"on\" && user.crossSessionNotify !== \"off\") {\n              user.crossSessionNotify = \"inherit\";\n            }\n          }\n          const outbound = normalizeOutbound(parsed.outbound);\n          if (outbound) parsed.outbound = outbound;\n          else delete parsed.outbound;\n          return parsed;\n        }\n      }\n    } catch {\n      // fall through to fresh state\n    }\n    return { users: {} };\n  }\n\n  private save(): void {\n    ensurePrivateDir(path.dirname(this.filePath));\n    const tempPath = `${this.filePath}.tmp-${process.pid}`;\n    try {\n      // 0o600 on both the temp file and the renamed target: the state file\n      // carries the WeChat↔session mapping and the queued outbound bodies.\n      writePrivateFile(tempPath, JSON.stringify(this.state, null, 2));\n      fs.renameSync(tempPath, this.filePath);\n    } catch (err) {\n      try {\n        if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);\n      } catch {\n        // best effort cleanup\n      }\n      throw err;\n    }\n  }\n\n  ensureUser(userId: string, cwd: string, opts?: { silent?: boolean }): UserState {\n    let user = this.state.users[userId];\n    if (!user) {\n      user = {\n        userId,\n        sessionId: \"\",\n        cwd,\n        silent: opts?.silent === true,\n        crossSessionNotify: \"inherit\",\n        watchedSessions: [],\n      };\n      this.state.users[userId] = user;\n      this.save();\n    } else {\n      // Backfill missing fields for users created before this feature\n      let changed = false;\n      if (user.crossSessionNotify !== \"on\" && user.crossSessionNotify !== \"off\" && user.crossSessionNotify !== \"inherit\") {\n        user.crossSessionNotify = \"inherit\";\n        changed = true;\n      }\n      if (!Array.isArray(user.watchedSessions)) {\n        user.watchedSessions = user.sessionId ? [user.sessionId] : [];\n        changed = true;\n      }\n      if (changed) this.save();\n    }\n    return user;\n  }\n\n  getUser(userId: string): UserState | undefined {\n    return this.state.users[userId];\n  }\n\n  update(userId: string, patch: Partial<UserState>): void {\n    const user = this.state.users[userId];\n    if (!user) return;\n    Object.assign(user, patch);\n    this.save();\n  }\n\n  /** Record that `userId` has been bound to `sessionId` (for cross-session recipient resolution). */\n  watchSession(userId: string, sessionId: string): void {\n    if (!sessionId) return;\n    const user = this.state.users[userId];\n    if (!user) return;\n    if (!Array.isArray(user.watchedSessions)) user.watchedSessions = [];\n    if (!user.watchedSessions.includes(sessionId)) {\n      user.watchedSessions.push(sessionId);\n      // Cap history to avoid unbounded growth\n      if (user.watchedSessions.length > 100) user.watchedSessions = user.watchedSessions.slice(-100);\n      this.save();\n    }\n  }\n\n  /** Return a defensive copy of the single-peer outbound snapshot. */\n  outbound(): OutboundState | undefined {\n    const value = this.state.outbound;\n    if (!value) return undefined;\n    return { ...value, queue: value.queue.map((item) => ({ ...item })) };\n  }\n\n  /** Replace and durably save the single-peer outbound snapshot. */\n  setOutbound(value: OutboundState): void {\n    const normalized = normalizeOutbound(value);\n    if (!normalized) throw new Error(\"invalid outbound state\");\n    this.state.outbound = normalized;\n    this.save();\n  }\n\n  /** Remove any durable outbound budget and queue. */\n  clearOutbound(): void {\n    if (!this.state.outbound) return;\n    delete this.state.outbound;\n    this.save();\n  }\n\n  /** Effective cross-session preference for display. */\n  getNotifyPreference(userId: string): \"inherit\" | \"on\" | \"off\" {\n    const user = this.state.users[userId];\n    if (!user) return \"inherit\";\n    if (user.crossSessionNotify === \"on\" || user.crossSessionNotify === \"off\") return user.crossSessionNotify;\n    return \"inherit\";\n  }\n\n  all(): UserState[] {\n    return Object.values(this.state.users);\n  }\n\n  /**\n   * Drop every persisted WeChat user. Logout / re-login must not keep the\n   * previous single-user peer, or a newly scanned account is ignored.\n   */\n  clearUsers(): void {\n    if (Object.keys(this.state.users).length === 0) return;\n    this.state.users = {};\n    this.save();\n  }\n}\n"
    },
    {
      "path": "src/weixin/auth.ts",
      "content": "/**\n * WeChat QR login flow + token persistence.\n * Ported from wechat-opencode (MIT) — https://github.com/pan17/wechat-opencode\n */\n\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { getBotQrcode, getQrcodeStatus } from \"./api.js\";\nimport { ensurePrivateDir, writePrivateFile } from \"../utils/secure-fs.js\";\n\nexport interface TokenData {\n  token: string;\n  baseUrl: string;\n  accountId: string;\n  userId: string;\n  savedAt: string;\n}\n\nfunction getAuthDir(storageDir: string): string {\n  return path.join(storageDir, \"auth\");\n}\n\nfunction getTokenPath(storageDir: string): string {\n  return path.join(getAuthDir(storageDir), \"token.json\");\n}\n\n/** Login was cancelled on purpose (dispose / logout / a new flow). */\nexport class LoginCancelledError extends Error {\n  readonly code = \"LOGIN_CANCELLED\";\n  constructor() {\n    super(\"login cancelled\");\n    this.name = \"LoginCancelledError\";\n  }\n}\n\n/**\n * One poll interval, cut short by `signal`. The timer is `unref`'d: a poll\n * cadence is never a reason to keep a shutting-down process alive.\n */\nfunction sleepUnlessAborted(ms: number, signal?: AbortSignal): Promise<void> {\n  return new Promise((resolve, reject) => {\n    if (signal?.aborted) {\n      reject(new LoginCancelledError());\n      return;\n    }\n    const onAbort = (): void => {\n      clearTimeout(timer);\n      reject(new LoginCancelledError());\n    };\n    const timer = setTimeout(() => {\n      signal?.removeEventListener(\"abort\", onAbort);\n      resolve();\n    }, ms);\n    timer.unref?.();\n    signal?.addEventListener(\"abort\", onAbort, { once: true });\n  });\n}\n\nexport function loadToken(storageDir: string): TokenData | null {\n  const tokenPath = getTokenPath(storageDir);\n  if (!fs.existsSync(tokenPath)) return null;\n  try {\n    return JSON.parse(fs.readFileSync(tokenPath, \"utf-8\")) as TokenData;\n  } catch {\n    return null;\n  }\n}\n\nexport function saveToken(storageDir: string, data: TokenData): void {\n  const authDir = getAuthDir(storageDir);\n  ensurePrivateDir(authDir);\n  const tokenPath = getTokenPath(storageDir);\n  // 0o600 (dir 0o700): this file IS the bot credential — anyone who can read\n  // it can send messages as the bot. On Windows Node ignores the mode and the\n  // inherited `%USERPROFILE%` ACLs apply (see src/utils/secure-fs.ts).\n  writePrivateFile(tokenPath, JSON.stringify(data, null, 2));\n}\n\nexport async function login(params: {\n  baseUrl: string;\n  botType?: string;\n  storageDir: string;\n  log: (msg: string) => void;\n  renderQrUrl?: (url: string) => void;\n  /**\n   * Cancels the scan poll (plugin dispose, logout, a superseded re-login).\n   * The loop runs for up to 5 minutes, so it must be cancellable: without it\n   * the plugin keeps a ref'd timer and an open socket per round long after the\n   * host has been told teardown finished, and the process never drains.\n   */\n  abortSignal?: AbortSignal;\n}): Promise<TokenData> {\n  const { baseUrl, botType, storageDir, log, renderQrUrl, abortSignal } = params;\n\n  log(\"Starting WeChat QR login...\");\n\n  const qrResp = await getBotQrcode({ baseUrl, botType, abortSignal });\n  const qrcodeUrl = qrResp.qrcode_img_content;\n\n  log(\"Please scan the QR code with WeChat:\");\n  if (renderQrUrl) {\n    renderQrUrl(qrcodeUrl);\n  } else {\n    log(`QR URL: ${qrcodeUrl}`);\n  }\n\n  const deadline = Date.now() + 5 * 60_000;\n  let currentQrcode = qrResp.qrcode;\n  let refreshCount = 0;\n\n  while (Date.now() < deadline) {\n    if (abortSignal?.aborted) throw new LoginCancelledError();\n    const statusResp = await getQrcodeStatus({ baseUrl, qrcode: currentQrcode, abortSignal });\n\n    switch (statusResp.status) {\n      case \"wait\":\n        break;\n      case \"scaned\":\n        log(\"QR scanned, please confirm in WeChat...\");\n        break;\n      case \"expired\": {\n        refreshCount++;\n        if (refreshCount > 3) {\n          throw new Error(\"QR code expired multiple times, please retry\");\n        }\n        log(`QR expired, refreshing (${refreshCount}/3)...`);\n        const newQr = await getBotQrcode({ baseUrl, botType, abortSignal });\n        currentQrcode = newQr.qrcode;\n        if (renderQrUrl) {\n          renderQrUrl(newQr.qrcode_img_content);\n        } else {\n          log(`New QR URL: ${newQr.qrcode_img_content}`);\n        }\n        break;\n      }\n      case \"confirmed\": {\n        log(\"Login successful!\");\n        const tokenData: TokenData = {\n          token: statusResp.bot_token!,\n          baseUrl: statusResp.baseurl || baseUrl,\n          accountId: statusResp.ilink_bot_id!,\n          userId: statusResp.ilink_user_id!,\n          savedAt: new Date().toISOString(),\n        };\n        saveToken(storageDir, tokenData);\n        log(`Bot ID: ${tokenData.accountId}`);\n        log(`Token saved to ${getTokenPath(storageDir)}`);\n        return tokenData;\n      }\n    }\n\n    await sleepUnlessAborted(1500, abortSignal);\n  }\n\n  throw new Error(\"Login timeout (5 minutes)\");\n}\n"
    },
    {
      "path": "src/weixin/media.ts",
      "content": "/**\n * AES-128-ECB encrypt/decrypt for WeChat CDN media.\n * Adapted from @tencent-weixin/openclaw-weixin cdn/aes-ecb.ts and\n * wechat-opencode (MIT) — https://github.com/pan17/wechat-opencode\n */\n\nimport crypto from \"node:crypto\";\nimport type { CDNMedia } from \"./types.js\";\n\nexport function encryptAesEcb(plaintext: Buffer, key: Buffer): Buffer {\n  const cipher = crypto.createCipheriv(\"aes-128-ecb\", key, null);\n  return Buffer.concat([cipher.update(plaintext), cipher.final()]);\n}\n\nexport function decryptAesEcb(ciphertext: Buffer, key: Buffer): Buffer {\n  const decipher = crypto.createDecipheriv(\"aes-128-ecb\", key, null);\n  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);\n}\n\n/**\n * Parse the AES key from CDN media reference.\n * The key can be either:\n *   - base64 → 16 raw bytes (use directly)\n *   - base64 → 32 hex chars → parse hex → 16 bytes\n */\nexport function parseAesKey(media: CDNMedia): Buffer | null {\n  const raw = media.aes_key;\n  if (!raw) return null;\n\n  const decoded = Buffer.from(raw, \"base64\");\n  if (decoded.length === 16) return decoded;\n  if (decoded.length === 32) {\n    const hexStr = decoded.toString(\"ascii\");\n    if (/^[0-9a-fA-F]{32}$/.test(hexStr)) {\n      return Buffer.from(hexStr, \"hex\");\n    }\n  }\n  return decoded.subarray(0, 16);\n}\n\nexport async function downloadAndDecrypt(\n  encryptQueryParam: string,\n  aesKey: Buffer,\n  cdnBaseUrl: string,\n  filekey?: string,\n): Promise<Buffer> {\n  let url = `${cdnBaseUrl}/download?encrypted_query_param=${encodeURIComponent(encryptQueryParam)}`;\n  if (filekey) {\n    url += `&filekey=${encodeURIComponent(filekey)}`;\n  }\n  const res = await fetch(url);\n  if (!res.ok) throw new Error(`CDN download failed: HTTP ${res.status}`);\n  const ciphertext = Buffer.from(await res.arrayBuffer());\n  return decryptAesEcb(ciphertext, aesKey);\n}\n\n/** Maximum retry attempts for CDN upload. */\nconst UPLOAD_MAX_RETRIES = 3;\n\nexport async function uploadToCdn(params: {\n  buffer: Buffer;\n  uploadParam: string;\n  aesKey: Buffer;\n  filekey: string;\n  cdnBaseUrl: string;\n  uploadUrl?: string;\n}): Promise<string> {\n  const encrypted = encryptAesEcb(params.buffer, params.aesKey);\n  const url = params.uploadUrl ?? `${params.cdnBaseUrl}/upload?encrypted_query_param=${encodeURIComponent(params.uploadParam)}&filekey=${encodeURIComponent(params.filekey)}`;\n\n  let downloadParam: string | undefined;\n  let lastError: unknown;\n\n  for (let attempt = 1; attempt <= UPLOAD_MAX_RETRIES; attempt++) {\n    try {\n      const res = await fetch(url, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/octet-stream\" },\n        body: new Uint8Array(encrypted),\n      });\n\n      if (res.status >= 400 && res.status < 500) {\n        const errMsg = res.headers.get(\"x-error-message\") ?? (await res.text());\n        throw new Error(`CDN upload client error ${res.status}: ${errMsg}`);\n      }\n      if (res.status !== 200) {\n        const errMsg = res.headers.get(\"x-error-message\") ?? `status ${res.status}`;\n        throw new Error(`CDN upload server error: ${errMsg}`);\n      }\n\n      downloadParam = res.headers.get(\"x-encrypted-param\") ?? undefined;\n      if (!downloadParam) {\n        const body = await res.text();\n        throw new Error(`CDN upload: missing x-encrypted-param header. Body: ${body}`);\n      }\n      break;\n    } catch (err) {\n      lastError = err;\n      if (err instanceof Error && err.message.includes(\"client error\")) throw err;\n      if (attempt < UPLOAD_MAX_RETRIES) {\n        // retry\n      }\n    }\n  }\n\n  if (!downloadParam) {\n    throw lastError instanceof Error\n      ? lastError\n      : new Error(`CDN upload failed after ${UPLOAD_MAX_RETRIES} attempts`);\n  }\n\n  return downloadParam ?? \"\";\n}\n"
    },
    {
      "path": "src/weixin/monitor.ts",
      "content": "/**\n * WeChat long-poll monitor loop.\n * Polls getUpdates, dispatches messages via callback.\n * Ported from wechat-opencode (MIT) — https://github.com/pan17/wechat-opencode\n */\n\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport {\n  getUpdates,\n  notifyStart,\n  isSessionTimeoutError,\n} from \"./api.js\";\nimport { writePrivateFile } from \"../utils/secure-fs.js\";\nimport type { WeixinMessage, GetUpdatesResp } from \"./types.js\";\n\nconst DEFAULT_LONG_POLL_TIMEOUT_MS = 35_000;\nconst MAX_CONSECUTIVE_FAILURES = 3;\nconst BACKOFF_DELAY_MS = 30_000;\nconst RETRY_DELAY_MS = 2_000;\nconst SESSION_EXPIRED_ERRCODE = -14;\n\n// Recovery-flow constants. Modeled on Tencent/openclaw-weixin PR #161\n// (https://github.com/Tencent/openclaw-weixin/pull/161): on errcode -14\n// the monitor calls notifyStart to rebuild the server-side session, then\n// either retries within seconds (success) or backs off exponentially up\n// to a 5-minute ceiling (failure). The original 60-minute wall would loop\n// indefinitely because getUpdates was retried without ever rebuilding the\n// session.\nconst NOTIFY_START_TIMEOUT_MS = 10_000;\nconst RECOVERY_INITIAL_BACKOFF_MS = 5_000;\nconst RECOVERY_MAX_BACKOFF_MS = 5 * 60_000;\nconst RECOVERY_BACKOFF_GROWTH = 2;\nconst RECOVERY_RETRY_AFTER_SUCCESS_MS = 5_000;\n// After this many consecutive notifyStart failures we surface a \"consider\n// re-scanning\" hint. Anything below this is recoverable noise; anything\n// above it is persistent enough that user action may help.\nconst RESCAN_HINT_AFTER_FAILURES = 6;\n\nexport interface MonitorOpts {\n  baseUrl: string;\n  token?: string;\n  storageDir: string;\n  abortSignal?: AbortSignal;\n  longPollTimeoutMs?: number;\n  log: (msg: string) => void;\n  onMessage: (msg: WeixinMessage) => void;\n  /** Gateway rejected the bot session (`-14`). Outbound should park. */\n  onSessionInvalid?: () => void;\n  /** A subsequent getUpdates succeeded; outbound may resume and flush. */\n  onSessionRecovered?: () => void;\n  /**\n   * notifyStart failed enough times that the user should re-scan.\n   * Fired once when the hint threshold is first crossed.\n   */\n  onSessionGiveUp?: () => void;\n}\n\nfunction getSyncBufPath(storageDir: string): string {\n  return path.join(storageDir, \"sync-buf.json\");\n}\n\nfunction loadSyncBuf(storageDir: string): string {\n  const p = getSyncBufPath(storageDir);\n  if (!fs.existsSync(p)) return \"\";\n  try {\n    const data = JSON.parse(fs.readFileSync(p, \"utf-8\")) as { get_updates_buf?: string };\n    return data.get_updates_buf ?? \"\";\n  } catch {\n    return \"\";\n  }\n}\n\nfunction saveSyncBuf(storageDir: string, buf: string): void {\n  // The long-poll cursor is not a secret, but it lives in the same private\n  // directory as the token: one mode policy for every file the plugin writes\n  // (0o700 dir / 0o600 file; Windows relies on inherited ACLs).\n  writePrivateFile(getSyncBufPath(storageDir), JSON.stringify({ get_updates_buf: buf }));\n}\n\n/** Drop the long-poll cursor so a new bot session does not resume the old one. */\nexport function clearSyncBuf(storageDir: string): void {\n  const p = getSyncBufPath(storageDir);\n  try {\n    if (fs.existsSync(p)) fs.unlinkSync(p);\n  } catch {\n    // best effort\n  }\n}\n\nfunction sleep(ms: number, signal?: AbortSignal): Promise<void> {\n  return new Promise((resolve, reject) => {\n    if (signal?.aborted) { reject(new Error(\"aborted\")); return; }\n    // Detach on the normal path too: this signal lives for the whole monitor\n    // run, so a listener per backoff would pile up (and trip Node's\n    // MaxListeners warning) on a channel that keeps retrying.\n    const onAbort = (): void => {\n      clearTimeout(t);\n      reject(new Error(\"aborted\"));\n    };\n    const t = setTimeout(() => {\n      signal?.removeEventListener(\"abort\", onAbort);\n      resolve();\n    }, ms);\n    signal?.addEventListener(\"abort\", onAbort, { once: true });\n  });\n}\n\nexport async function startMonitor(opts: MonitorOpts): Promise<void> {\n  const { baseUrl, token, storageDir, abortSignal, log, onMessage, onSessionInvalid, onSessionRecovered, onSessionGiveUp } = opts;\n\n  let getUpdatesBuf = loadSyncBuf(storageDir);\n  if (getUpdatesBuf) {\n    log(`Resuming from previous sync buf (${getUpdatesBuf.length} bytes)`);\n  } else {\n    log(\"No previous sync buf, starting fresh\");\n  }\n\n  let nextTimeoutMs = opts.longPollTimeoutMs ?? DEFAULT_LONG_POLL_TIMEOUT_MS;\n  let consecutiveFailures = 0;\n\n  // Recovery state — see file header. Reset to initial on any successful\n  // poll OR a successful notifyStart; grows on consecutive notifyStart\n  // failures up to RECOVERY_MAX_BACKOFF_MS.\n  let recoveryBackoffMs = RECOVERY_INITIAL_BACKOFF_MS;\n  let consecutiveNotifyStartFailures = 0;\n\n  const resetRecoveryState = (): void => {\n    recoveryBackoffMs = RECOVERY_INITIAL_BACKOFF_MS;\n    consecutiveNotifyStartFailures = 0;\n  };\n\n  /**\n   * Try to rebuild the server-side session via notifyStart. Returns true\n   * on success, false on failure (or abort). The caller is responsible\n   * for the subsequent backoff/retry logic; this only attempts the call.\n   */\n  const tryRecover = async (): Promise<boolean> => {\n    log(\n      `Session timeout suspected — calling notifyStart to rebuild the server-side session...`,\n    );\n    try {\n      await notifyStart({\n        baseUrl,\n        token,\n        timeoutMs: NOTIFY_START_TIMEOUT_MS,\n        abortSignal,\n      });\n      log(`notifyStart succeeded; server session rebuilt.`);\n      return true;\n    } catch (e) {\n      if (abortSignal?.aborted) return false;\n      log(`notifyStart failed: ${String(e)}`);\n      return false;\n    }\n  };\n\n  /**\n   * Apply the recovery outcome: reset state + short retry on success,\n   * grow the backoff on failure (and surface a re-scan hint once the\n   * threshold is crossed). All sleeps respect the abort signal.\n   */\n  const applyRecoveryOutcome = async (recovered: boolean): Promise<void> => {\n    if (recovered) {\n      resetRecoveryState();\n      try {\n        await sleep(RECOVERY_RETRY_AFTER_SUCCESS_MS, abortSignal);\n      } catch {\n        if (abortSignal?.aborted) return;\n      }\n      return;\n    }\n\n    consecutiveNotifyStartFailures++;\n    const waitMs = recoveryBackoffMs;\n    recoveryBackoffMs = Math.min(\n      recoveryBackoffMs * RECOVERY_BACKOFF_GROWTH,\n      RECOVERY_MAX_BACKOFF_MS,\n    );\n\n    if (consecutiveNotifyStartFailures >= RESCAN_HINT_AFTER_FAILURES) {\n      log(\n        `notifyStart has failed ${consecutiveNotifyStartFailures} consecutive times ` +\n          `(current backoff ${waitMs / 1000}s, next ${recoveryBackoffMs / 1000}s). ` +\n          `If this persists, please re-scan the QR code to get a fresh bot_token.`,\n      );\n      if (consecutiveNotifyStartFailures === RESCAN_HINT_AFTER_FAILURES) {\n        onSessionGiveUp?.();\n      }\n    } else {\n      log(\n        `notifyStart failed; backing off ${waitMs / 1000}s before retrying ` +\n          `(next attempt in up to ${recoveryBackoffMs / 1000}s).`,\n      );\n    }\n\n    try {\n      await sleep(waitMs, abortSignal);\n    } catch {\n      if (abortSignal?.aborted) return;\n    }\n  };\n\n  while (!abortSignal?.aborted) {\n    try {\n      const resp: GetUpdatesResp = await getUpdates({\n        baseUrl,\n        token,\n        get_updates_buf: getUpdatesBuf,\n        timeoutMs: nextTimeoutMs,\n        abortSignal,\n      });\n      // An old poll may resolve while stop/reload is cancelling it. Do not\n      // advance the cursor or dispatch its messages after ownership ended.\n      if (abortSignal?.aborted) return;\n\n      if (resp.longpolling_timeout_ms != null && resp.longpolling_timeout_ms > 0) {\n        nextTimeoutMs = resp.longpolling_timeout_ms;\n      }\n\n      const isApiError =\n        (resp.ret !== undefined && resp.ret !== 0) ||\n        (resp.errcode !== undefined && resp.errcode !== 0);\n\n      if (isApiError) {\n        const isSessionExpired =\n          resp.errcode === SESSION_EXPIRED_ERRCODE ||\n          resp.ret === SESSION_EXPIRED_ERRCODE;\n\n        if (isSessionExpired) {\n          onSessionInvalid?.();\n          const recovered = await tryRecover();\n          if (abortSignal?.aborted) return;\n          await applyRecoveryOutcome(recovered);\n          continue;\n        }\n\n        consecutiveFailures++;\n        log(`getUpdates failed: ret=${resp.ret} errcode=${resp.errcode} errmsg=${resp.errmsg ?? \"\"} (${consecutiveFailures}/${MAX_CONSECUTIVE_FAILURES})`);\n\n        if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {\n          log(`${MAX_CONSECUTIVE_FAILURES} consecutive failures, backing off ${BACKOFF_DELAY_MS / 1000}s`);\n          consecutiveFailures = 0;\n          await sleep(BACKOFF_DELAY_MS, abortSignal);\n        } else {\n          await sleep(RETRY_DELAY_MS, abortSignal);\n        }\n        continue;\n      }\n\n      consecutiveFailures = 0;\n      resetRecoveryState();\n      onSessionRecovered?.();\n\n      if (resp.get_updates_buf != null && resp.get_updates_buf !== \"\") {\n        saveSyncBuf(storageDir, resp.get_updates_buf);\n        getUpdatesBuf = resp.get_updates_buf;\n      }\n\n      for (const msg of resp.msgs ?? []) {\n        if (abortSignal?.aborted) return;\n        onMessage(msg);\n      }\n    } catch (err) {\n      if (abortSignal?.aborted) return;\n\n      if (isSessionTimeoutError(err)) {\n        // Parseable JSON `-14` now throws SessionTimeoutError from apiPost\n        // (HTTP 200 + body). The iLink gateway can also return HTTP 200\n        // with a malformed Content-Length so undici throws before we read\n        // the JSON. Both mean the bot session is dead — disable outbound\n        // and rebuild via notifyStart.\n        onSessionInvalid?.();\n        const recovered = await tryRecover();\n        if (abortSignal?.aborted) return;\n        await applyRecoveryOutcome(recovered);\n        continue;\n      }\n\n      consecutiveFailures++;\n      log(`getUpdates error (${consecutiveFailures}/${MAX_CONSECUTIVE_FAILURES}): ${String(err)}`);\n\n      try {\n        if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {\n          log(`${MAX_CONSECUTIVE_FAILURES} consecutive failures, backing off ${BACKOFF_DELAY_MS / 1000}s`);\n          consecutiveFailures = 0;\n          await sleep(BACKOFF_DELAY_MS, abortSignal);\n        } else {\n          await sleep(RETRY_DELAY_MS, abortSignal);\n        }\n      } catch {\n        if (abortSignal?.aborted) return;\n      }\n    }\n  }\n}\n"
